    private val byKey = all.associateBy { it.key }
    private val cache = HashMap<String, ImageVector>()

    const val DEFAULT = "devices_other"

    fun label(key: String?): String = byKey[key]?.label ?: byKey.getValue(DEFAULT).label

    fun vector(key: String?): ImageVector {
        val def = byKey[key] ?: byKey.getValue(DEFAULT)
        return cache.getOrPut(def.key) {
            val b = ImageVector.Builder(
                name = def.key,
                defaultWidth = 24.dp,
                defaultHeight = 24.dp,
                viewportWidth = 24f,
                viewportHeight = 24f,
            )
            def.paths.forEach { b.addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) }
            b.build()
        }
    }
